package edu.pe.cibertec.saibm.usuario.application.port.in; import java.util.*; public interface UserUseCase {UserView create(UserCommand c,String correlation);UserView find(UUID id,Actor actor);List<UserView> list(String query,Actor actor);UserView update(UUID id,UserCommand c,Actor actor,String correlation);void deactivate(UUID id,Actor actor,String correlation);void reactivate(UUID id,Actor actor,String correlation);record UserCommand(String firstName,String lastName,String dni,String email){}record Actor(String subject,boolean admin){public boolean owns(UUID id){return subject!=null&&subject.equals(id.toString());}}record UserView(UUID id,String firstName,String lastName,String dni,String email,boolean active,String legacyUserId){} }
